```rust
//! CRC32C (Castagnoli, отражённый полином 0x1EDC6F41).

/// Полином Castagnoli 0x1EDC6F41 в отражённом виде (младший бит — первый).
const POLY_REFLECTED: u32 = 0x82F6_3B78;

const fn make_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut i = 0usize;
    while i < 256 {
        let mut crc = i as u32;
        let mut bit = 0;
        while bit < 8 {
            crc = if crc & 1 == 1 { (crc >> 1) ^ POLY_REFLECTED } else { crc >> 1 };
            bit += 1;
        }
        table[i] = crc;
        i += 1;
    }
    table
}

static TABLE: [u32; 256] = make_table();

/// crc32c от `bytes`, инициализация/финализация по стандарту CRC-32C.
pub const CRC32C_INIT: u32 = 0;

pub fn crc32c(bytes: &[u8]) -> u32 { crc32c_update(0, bytes) }

pub fn crc32c_update(previous: u32, bytes: &[u8]) -> u32 {
    let mut crc = !previous;
    for &byte in bytes {
        let idx = ((crc ^ u32::from(byte)) & 0xFF) as usize;
        crc = TABLE[idx] ^ (crc >> 8);
    }
    !crc
}
```

