    /// Создаёт первый сегмент: `segment_id` — номер файла (log/000042.seg → 42).
    pub fn create(mut store: S, kind: SegmentKind, segment_id: u64, seq_first: u64, created_ns: u64, prev_crc: u32) -> Result<Self, Error> {
        let header = SegmentHeader::new(kind, seq_first, created_ns, prev_crc);
