pub fn header(&mut self) -> Result<SegmentHeader, Error> {
    if let Some(h) = self.header { return Ok(h); }
    debug_assert!(self.pos == 0);
    if self.buf.len() < SEGMENT_HEADER_LEN {
        self.status = ReaderStatus::Torn { at: self.buf.len() };
        self.stopped = true;
        return Err(Error::IncompleteSegmentHeader { available: self.buf.len() });
    }
    match SegmentHeader::decode(&self.buf[..SEGMENT_HEADER_LEN]) {
        Ok(h) => { self.header = Some(h); self.pos = SEGMENT_HEADER_LEN; Ok(h) }
        Err(e) => { self.status = ReaderStatus::Damaged { at: 0 }; self.stopped = true; Err(e) }
    }
}
```
Hmm: if stopped is set due to short header, later header() calls: header is None, we'd re-set status. Fine (idempotent). But careful: `next_record` calls header() each time.

`parse_record_at(buf, offset, expected: Option<u64>) -> Result<Record, Error>`:
```rust
fn parse_record_at(buf: &[u8], offset: usize, expected_seq: Option<u64>) -> Result<Record<'_>, Error> {
    let available = buf.len().saturating_sub(offset);
    if available < RECORD_HEADER_LEN { return Err(Error::RecordTooShort { available }); }
    if buf[offset..offset+4] != RECORD_MAGIC_BYTES { return Err(Error::BadRecordMagic); }
    let header = RecordHeader::decode(&buf[offset..offset+RECORD_HEADER_LEN])?;
    let len = header.len as usize;
    if len > MAX_RECORD { return Err(Error::RecordLenTooLarge { len: header.len, max: MAX_RECORD as u32 }); }
    if len % 8 != 0 { return Err(Error::RecordLenUnaligned { len: header.len }); }
    let end = offset + RECORD_HEADER_LEN + len;
    if end > buf.len() { return Err(Error::RecordOutOfBounds { offset, len, available: buf.len() }); }
    let payload = &buf[offset+RECORD_HEADER_LEN..end];
    let computed = crc32c(payload);
    if computed != header.crc32c { return Err(Error::BadRecordCrc { stored: header.crc32c, computed }); }
    if let Some(expected) = expected_seq { if header.seq != expected { return Err(Error::UnexpectedSeq { expected, actual: header.seq }); } }
    Ok(Record { header, payload })
}
```
