pub fn next_record(&mut self) -> Option<Record<'a>> {
    if self.stopped { return None; }
    loop {
        if self.header().is_err() { return None; }
        if self.pos >= self.buf.len() {
            self.stopped = true;
            return None;   // status remains Clean if it was Clean
        }
        let expected = self.last_seq.map(|s| s.wrapping_add(1)); // Option<u64>
        match parse_record_at(self.buf, self.pos, expected) {
            Ok(rec) => {
                self.last_seq = Some(rec.header.seq);
                self.consumed = self.pos + rec.header.record_len();
                self.pos = self.consumed;
                self.records += 1;
                return Some(rec);
            }
            Err(_) => {
                // resync
                match self.resync() {
                    Some(next) => { self.pos = next; /* loop continues: will parse and yield */ }
                    None => { self.stopped = true; return None; }
                }
