impl Checkpoint {
    /// payload записи вида `checkpoint` (kind 8): [версия схемы][CBOR][выравнивание нулями до 8]
    pub fn encode_payload(&self) -> Result<Vec<u8>, Error> {
        let mut body = Vec::new();
        body.push(CHECKPOINT_SCHEMA_VERSION);
        let mut cbor = Vec::new();
        ciborium::ser::into_writer(self, &mut cbor).map_err(|_| Error::CborEncode)?;
        // control: canonical form
        let consumed = crate::checkpoint::canonical::scan(&cbor).map_err(Error::NonCanonicalCbor)?;
        debug_assert_eq!(consumed, cbor.len());
        body.extend_from_slice(&cbor);
        let padded = align8(body.len());
        body.resize(padded, 0);
        Ok(body)
    }

    pub fn decode_payload(bytes: &[u8]) -> Result<Self, Error> {
        let version = *bytes.first().ok_or(Error::UnsupportedSchemaVersion { stored: 0, supported: CHECKPOINT_SCHEMA_VERSION })?;
        if version != CHECKPOINT_SCHEMA_VERSION { return Err(Error::UnsupportedSchemaVersion { stored: version, supported: CHECKPOINT_SCHEMA_VERSION }); }
        let rest = &bytes[1..];
        let consumed = canonical::scan(rest).map_err(Error::NonCanonicalCbor)?;
        if rest[consumed..].iter().any(|b| *b != 0) { return Err(Error::TrailingBytes { at: 1 + consumed }); }
        ciborium::de::from_reader(&rest[..consumed]).map_err(|_| Error::CborDecode)
    }
}
