//!
//! Одна перечисляемая ошибка на весь crate: формат — это один протокол
//! (ARCHITECTURE §5.2), и вызывающей стороне полезно видеть его целиком.
//! Ошибки не содержат аллокаций, `Copy`.

use core::fmt;

/// Ошибка разбора или записи сегмента.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    /// Заголовок сегмента короче 64 байт — файл оборван на заголовке.
    IncompleteSegmentHeader {
        /// Сколько байт реально есть.
        available: usize,
    },
    /// Первые 8 байт заголовка не равны `AIOSSEG1`.
    BadSegmentMagic,
    /// `crc32c` заголовка сегмента не сошёлся.
    BadHeaderCrc {
        /// Значение из поля `hdr_crc`.
        stored: u32,
        /// Значение, посчитанное по фактическим байтам.
        computed: u32,
    },
    /// Версия формата сегмента не поддерживается.
    UnsupportedSegmentVersion {
        /// Версия из заголовка.
        stored: u16,
        /// Версия, которую понимает эта реализация.
        supported: u16,
    },
    /// Неизвестный `kind` сегмента (допустимы 1=session, 2=audit, 3=index).
    UnknownSegmentKind {
        /// Значение из заголовка.
        stored: u16,
    },
    /// Остаток записи короче 32-байтного заголовка записи.
    RecordTooShort {
        /// Сколько байт осталось до конца буфера.
        available: usize,
    },
    /// Запись не начинается с magic `0x4149_4F53`.
    BadRecordMagic {
        /// Смещение, на котором ожидалась запись.
        offset: usize,
    },
    /// `len` записи больше [`crate::MAX_RECORD`].
    RecordLenTooLarge {
        /// Значение поля `len`.
        len: u32,
        /// Предел, [`crate::MAX_RECORD`].
        max: u32,
    },
    /// `len` записи не кратен 8 — нарушен инвариант resync (§5.2).
    RecordLenUnaligned {
        /// Значение поля `len`.
        len: u32,
    },
    /// Запись выходит за границу буфера: в файле она оборвана.
    RecordOutOfBounds {
        /// Смещение начала записи.
        offset: usize,
        /// Значение поля `len`.
        len: u32,
        /// Длина буфера, в котором искали запись.
        available: usize,
    },
    /// `crc32c` payload не сошёлся.
    BadRecordCrc {
        /// Значение из поля `crc32c`.
        stored: u32,
        /// Значение, посчитанное по payload.
        computed: u32,
    },
    /// Нарушен инвариант строгой последовательности `seq` (§5.2).
    UnexpectedSeq {
        /// Ожидаемое значение.
        expected: u64,
        /// Фактическое значение из заголовка записи.
        actual: u64,
    },
    /// Писатель не принял payload: длина больше [`crate::MAX_RECORD`].
    PayloadTooLarge {
        /// Длина payload.
        len: usize,
        /// Предел, [`crate::MAX_RECORD`].
        max: usize,
    },
    /// Писатель не принял payload: длина не кратна 8 (§5.2).
    PayloadUnaligned {
        /// Длина payload.
        len: usize,
    },
    /// Нижележащее хранилище сегментов сообщило об ошибке (диск, ФС, буфер).
    Store,
    /// Запись не того вида, который ожидался.
    UnexpectedRecordKind {
        /// Ожидаемый `kind`.
        expected: u8,
        /// Фактический `kind`.
        actual: u8,
    },
    /// Payload пуст: в нём нет даже байта версии схемы (§5.12).
    #[cfg(feature = "cbor")]
    SchemaVersionMissing,
    /// Версия схемы payload не поддерживается (§5.12: несовпадение = отказ разбора).
    #[cfg(feature = "cbor")]
    UnsupportedSchemaVersion {
        /// Версия из первого байта payload.
        stored: u8,
        /// Версия, которую понимает эта реализация.
        supported: u8,
    },
    /// CBOR не в канонической форме (§5.12); строка — причина.
    #[cfg(feature = "cbor")]
    NonCanonicalCbor(&'static str),
    /// Сериализация в CBOR не удалась.
    #[cfg(feature = "cbor")]
    CborEncode,
    /// Разбор CBOR не удался (не тот тип, обрезанные данные).
    #[cfg(feature = "cbor")]
    CborDecode,
    /// После CBOR-значения в payload остались непустые байты.
    #[cfg(feature = "cbor")]
    TrailingBytes {
        /// Смещение в payload, с которого начинается мусор.
        at: usize,
    },
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::IncompleteSegmentHeader { available } => write!(
                f,
                "заголовок сегмента оборван: {available} из {} байт",
                crate::SEGMENT_HEADER_LEN
            ),
            Error::BadSegmentMagic => write!(f, "не совпал magic сегмента AIOSSEG1"),
            Error::BadHeaderCrc { stored, computed } => write!(
                f,
                "crc32c заголовка сегмента не сошёлся: в файле {stored:#010x}, посчитан {computed:#010x}"
            ),
            Error::UnsupportedSegmentVersion { stored, supported } => write!(
                f,
                "версия сегмента {stored} не поддерживается (поддерживается {supported})"
            ),
            Error::UnknownSegmentKind { stored } => {
                write!(f, "неизвестный kind сегмента {stored}")
            }
            Error::RecordTooShort { available } => write!(
                f,
                "остаток записи короче заголовка: {available} из {} байт",
                crate::RECORD_HEADER_LEN
            ),
            Error::BadRecordMagic { offset } => {
                write!(f, "нет magic записи на смещении {offset}")
            }
            Error::RecordLenTooLarge { len, max } => {
                write!(f, "len записи {len} больше предела {max}")
            }
            Error::RecordLenUnaligned { len } => {
                write!(f, "len записи {len} не кратен 8")
            }
            Error::RecordOutOfBounds {
                offset,
                len,
                available,
            } => write!(
                f,
                "запись на смещении {offset} с len {len} выходит за буфер {available}"
            ),
            Error::BadRecordCrc { stored, computed } => write!(
                f,
                "crc32c payload не сошёлся: в записи {stored:#010x}, посчитан {computed:#010x}"
            ),
            Error::UnexpectedSeq { expected, actual } => {
                write!(f, "seq {actual} вместо ожидаемого {expected}")
            }
            Error::PayloadTooLarge { len, max } => {
                write!(f, "payload {len} байт больше предела {max}")
            }
            Error::PayloadUnaligned { len } => {
                write!(f, "payload {len} байт не кратен 8")
            }
            Error::Store => write!(f, "ошибка хранилища сегментов"),
            Error::UnexpectedRecordKind { expected, actual } => {
                write!(f, "вид записи {actual} вместо ожидаемого {expected}")
            }
            #[cfg(feature = "cbor")]
            Error::SchemaVersionMissing => write!(f, "payload пуст: нет байта версии схемы"),
            #[cfg(feature = "cbor")]
            Error::UnsupportedSchemaVersion { stored, supported } => write!(
                f,
                "версия схемы {stored} не поддерживается (поддерживается {supported})"
            ),
            #[cfg(feature = "cbor")]
            Error::NonCanonicalCbor(reason) => {
                write!(f, "CBOR не в канонической форме: {reason}")
            }
            #[cfg(feature = "cbor")]
            Error::CborEncode => write!(f, "не удалось сериализовать CBOR"),
            #[cfg(feature = "cbor")]
            Error::CborDecode => write!(f, "не удалось разобрать CBOR"),
            #[cfg(feature = "cbor")]
            Error::TrailingBytes { at } => {
                write!(f, "после CBOR остались лишние байты со смещения {at}")
            }
        }
    }
}

impl core::error::Error for Error {}
"}

