//!
//! ARCHITECTURE §5.2: `crc32c` — только дешёвый детект обрыва записи;
//! криптографическая целостность аудита — отдельная blake3-цепочка (§7.4),
//! здесь её нет.
//!
//! Полином Castagnoli `0x1EDC6F41`; реализация отражённая (как в iSCSI/SCTP):
//! младший бит многочлена обрабатывается первым, вход/выход отражаются.
//! Внешних крейтов нет, таблица считается на этапе компиляции.

/// Полином Castagnoli `0x1EDC6F41` в отражённом виде.
const POLY_REFLECTED: u32 = 0x82F6_3B78;

/// Начальное значение CRC-32C до отражения.
const INIT: u32 = 0xFFFF_FFFF;

/// Таблица на 256 значений, посчитанная при компиляции.
const fn make_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    let mut index = 0;
    while index < 256 {
        let mut crc = index as u32;
        let mut bit = 0;
        while bit < 8 {
            crc = if crc & 1 == 1 {
                (crc >> 1) ^ POLY_REFLECTED
            } else {
                crc >> 1
            };
            bit += 1;
        }
        table[index] = crc;
        index += 1;
    }
    table
}

static TABLE: [u32; 256] = make_table();

/// `crc32c` от `bytes` (инициализация и финализация по стандарту CRC-32C).
///
/// Контрольное значение: `crc32c(b"123456789") == 0xE306_9283`.
pub fn crc32c(bytes: &[u8]) -> u32 {
    crc32c_update(0, bytes)
}

/// Продолжает CRC: `crc32c_update(crc32c(a), b) == crc32c(a ++ b)`.
///
/// Нужен, чтобы считать crc сегмента потоком, не держа его целиком в памяти.
pub fn crc32c_update(previous: u32, bytes: &[u8]) -> u32 {
    let mut crc = !previous;
    for &byte in bytes {
        let index = ((crc ^ u32::from(byte)) & 0xFF) as usize;
        crc = TABLE[index] ^ (crc >> 8);
    }
    !crc
}
