{"content": "//! Заголовок сегмента — ARCHITECTURE §5.2.
//!
//! Раскладка (little-endian, ровно 64 байта):
//!
//! ```text
//! magic      [8]  "AIOSSEG1"
//! version    u16
//! kind       u16  1=session 2=audit 3=index
//! seq_first  u64
//! created_ns u64
//! prev_crc   u32  crc32c предыдущего сегмента (цепочка на уровне файлов)
//! hdr_crc    u32
//! reserved   [16]
//! ```
//!
//! Документ требует ровно 64 байта, а перечисленные поля занимают 52. Чтобы
//! выполнить оба требования, после `reserved` добавлены 12 нулевых байт
//! выравнивания до 64 (`PADDING`); поле `reserved` остаётся ровно `[u8; 16]`,
//! как в документе. Это единственное расхождение с текстом §5.2, оно
//! зафиксировано в отчёте задачи T5.

use crate::crc32c::crc32c;
use crate::error::Error;

/// Magic заголовка сегмента.
pub const SEGMENT_MAGIC: [u8; 8] = *b"AIOSSEG1";

/// Полный размер заголовка сегмента, байт.
pub const SEGMENT_HEADER_LEN: usize = 64;

/// Версия формата сегмента, которую понимает эта реализация.
pub const SEGMENT_VERSION: u16 = 1;

/// Размер поля `reserved`, байт (документ: `reserved [16]`).
pub const SEGMENT_RESERVED_LEN: usize = 16;

// Смещения полей внутри заголовка.
const OFF_MAGIC: usize = 0;
const OFF_VERSION: usize = 8;
const OFF_KIND: usize = 10;
const OFF_SEQ_FIRST: usize = 12;
const OFF_CREATED_NS: usize = 20;
const OFF_PREV_CRC: usize = 28;
const OFF_HDR_CRC: usize = 32;
const OFF_RESERVED: usize = 36;
const OFF_PADDING: usize = OFF_RESERVED + SEGMENT_RESERVED_LEN; // 52

/// Сколько нулевых байт выравнивания добавлено, чтобы заголовок стал 64-байтным.
pub const SEGMENT_PADDING_LEN: usize = SEGMENT_HEADER_LEN - OFF_PADDING; // 12

/// Вид сегмента (§5.1: транскрипт сессии, аудит, индекс).
#[repr(u16)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SegmentKind {
    /// `log/NNNNNN.seg` — append-only транскрипт сессии.
    Session = 1,
    /// `audit/audit.seg` — глобальный hash-chained журнал.
    Audit = 2,
    /// Кэш индекса памяти (перестраиваемый).
    Index = 3,
}

impl SegmentKind {
    /// Числовое значение поля `kind`.
    pub const fn as_u16(self) -> u16 {
        self as u16
    }

    /// Разбирает `kind` из заголовка.
    pub fn from_u16(value: u16) -> Result<Self, Error> {
        match value {
            1 => Ok(SegmentKind::Session),
            2 => Ok(SegmentKind::Audit),
            3 => Ok(SegmentKind::Index),
            stored => Err(Error::UnknownSegmentKind { stored }),
        }
    }
}

/// Заголовок сегмента (§5.2).
///
/// `hdr_crc` хранится, но при кодировании всегда пересчитывается: `crc32c`
/// по всем 64 байтам заголовка, в которых поле `hdr_crc` обнулено.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SegmentHeader {
    /// Версия формата.
    pub version: u16,
    /// Вид сегмента.
    pub kind: SegmentKind,
    /// `seq` первой записи сегмента.
    pub seq_first: u64,
    /// Момент создания сегмента, монотонные наносекунды.
    pub created_ns: u64,
    /// `crc32c` предыдущего файла сегмента (0 для первого).
    pub prev_crc: u32,
    /// `crc32c` самого заголовка (пересчитывается при кодировании).
    pub hdr_crc: u32,
    /// Зарезервировано под расширение формата; при записи — нули.
    pub reserved: [u8; SEGMENT_RESERVED_LEN],
}

impl SegmentHeader {
    /// Создаёт заголовок текущей версии с нулевым `reserved`.
    ///
    /// `prev_crc` — `crc32c` предыдущего файла сегмента, для самого первого
    /// сегмента `0`.
    pub fn new(kind: SegmentKind, seq_first: u64, created_ns: u64, prev_crc: u32) -> Self {
        let mut header = SegmentHeader {
            version: SEGMENT_VERSION,
            kind,
            seq_first,
            created_ns,
            prev_crc,
            hdr_crc: 0,
            reserved: [0u8; SEGMENT_RESERVED_LEN],
        };
        header.hdr_crc = header.computed_crc();
        header
    }

    /// Кодирует заголовок в ровно 64 байта (little-endian, `hdr_crc` пересчитан).
    pub fn encode(&self) -> [u8; SEGMENT_HEADER_LEN] {
        let mut bytes = [0u8; SEGMENT_HEADER_LEN];
        bytes[OFF_MAGIC..OFF_MAGIC + 8].copy_from_slice(&SEGMENT_MAGIC);
        bytes[OFF_VERSION..OFF_VERSION + 2].copy_from_slice(&self.version.to_le_bytes());
        bytes[OFF_KIND..OFF_KIND + 2].copy_from_slice(&self.kind.as_u16().to_le_bytes());
