use crate::error::Error;

/// Magic записи: `0x41_49_4F_53` («AIOS» в порядке байт big-endian).
///
/// На диск поле пишется little-endian, то есть байтами `53 4F 49 41` — так
/// требует общий little-endian формат §5.2. Для поиска magic в файле есть
/// [`RECORD_MAGIC_BYTES`].
pub const RECORD_MAGIC: u32 = 0x4149_4F53;

/// Байты magic записи в файле (little-endian представление [`RECORD_MAGIC`]).
pub const RECORD_MAGIC_BYTES: [u8; 4] = RECORD_MAGIC.to_le_bytes();

/// Размер заголовка записи вместе с выравниванием, байт.
pub const RECORD_HEADER_LEN: usize = 32;

/// Максимальная длина payload одной записи: 1 МиБ (§5.2).
pub const MAX_RECORD: usize = 1024 * 1024;

/// `flags` bit0: payload сжат LZ4 frame.
pub const FLAG_LZ4: u8 = 0x01;

/// `flags` bit1: payload ссылается на внешний блоб.
pub const FLAG_EXTERNAL_BLOB: u8 = 0x02;

// Смещения полей внутри заголовка записи.
const OFF_MAGIC: usize = 0;
const OFF_LEN: usize = 4;
const OFF_CRC: usize = 8;
const OFF_KIND: usize = 12;
const OFF_FLAGS: usize = 13;
const OFF_PAD: usize = 14;
const OFF_SEQ: usize = 16;
const OFF_TS_NS: usize = 24;

