    UserIn = 1,
    /// Текст ответа модели, usage, модель.
    ModelOut = 2,
    /// Шаги плана, уверенность.
    Plan = 3,
    /// Имя возможности, аргументы (redact), хеш результата.
    CapCall = 4,
    /// Вердикт policy engine, правило, причина.
    Policy = 5,
    /// Запись факта в семантическую память: id, скоуп, провенанс.
    MemWrite = 6,
    /// Ссылка на снапшот KV и число токенов префикса.
