    /// Флаги, [`FLAG_LZ4`] и [`FLAG_EXTERNAL_BLOB`].
    pub flags: u8,
    /// Монотонный номер записи.
    pub seq: u64,
    /// Время записи, монотонные наносекунды.
    pub ts_ns: u64,
