            bytes[OFF_LEN..OFF_LEN + 4]
                .try_into()
                .expect("4 байта"),
        );
        if len as usize > MAX_RECORD {
            return Err(Error::RecordLenTooLarge {
                len,
                max: MAX_RECORD as u32,
            });
        }
        if len % 8 != 0 {
            return Err(Error::RecordLenUnaligned { len });
