            flags: bytes[OFF_FLAGS],
            seq: u64::from_le_bytes(
                bytes[OFF_SEQ..OFF_SEQ + 8]
                    .try_into()
                    .expect("8 байт"),
            ),
            ts_ns: u64::from_le_bytes(
                bytes[OFF_TS_NS..OFF_TS_NS + 8]
                    .try_into()
                    .expect("8 байт"),
            ),
        })
    }

