    pub const fn record_len(&self) -> usize {
        RECORD_HEADER_LEN + self.len as usize
    }

    /// `true`, если payload сжат LZ4 (`flags` bit0).
    pub const fn is_lz4(&self) -> bool {
        self.flags & FLAG_LZ4 != 0
    }

    /// `true`, если payload ссылается на внешний блоб (`flags` bit1).
    pub const fn has_external_blob(&self) -> bool {
        self.flags & FLAG_EXTERNAL_BLOB != 0
    }
}

/// Запись сегмента: заголовок и payload, взятый из буфера сегмента.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Record<'a> {
    /// Заголовок записи.
    pub header: RecordHeader,
    /// Payload ровно `header.len` байт (может включать нулевое выравнивание
    /// до кратного 8 — см. `Writer::append`).
    pub payload: &'a [u8],
}

impl<'a> Record<'a> {
    /// `seq` записи.
    pub const fn seq(&self) -> u64 {
        self.header.seq
    }

    /// `kind` записи.
    pub const fn kind(&self) -> u8 {
        self.header.kind
    }

    /// `flags` записи.
    pub const fn flags(&self) -> u8 {
        self.header.flags
    }

    /// Полный размер записи на диске в байтах.
    pub const fn record_len(&self) -> usize {
        RECORD_HEADER_LEN + self.header.len as usize
    }
}

/// Разбирает запись по смещению `offset` в буфере сегмента.
///
/// Проверяет magic, `len` (предел и кратность 8), границы буфера и `crc32c`
/// payload. `seq` здесь не проверяется — это делает [`crate::SegmentReader`],
/// который знает, какая запись ожидается следующей.
pub fn parse_record_at(bytes: &[u8], offset: usize) -> Result<Record<'_>, Error> {
    let available = bytes.len().saturating_sub(offset);
    if available < RECORD_HEADER_LEN {
        return Err(Error::RecordTooShort { available });
    }
    if bytes[offset..offset + 4] != RECORD_MAGIC_BYTES {
        return Err(Error::BadRecordMagic { offset });
    }
    let header = RecordHeader::decode(&bytes[offset..offset + RECORD_HEADER_LEN])?;
    let len = header.len as usize;
    let end = offset + RECORD_HEADER_LEN + len;
    if end > bytes.len() {
        return Err(Error::RecordOutOfBounds {
            offset,
            len: header.len,
            available: bytes.len(),
        });
    }
    let payload = &bytes[offset + RECORD_HEADER_LEN..end];
    let computed = crc32c(payload);
    if computed != header.crc32c {
        return Err(Error::BadRecordCrc {
            stored: header.crc32c,
            computed,
        });
    }
    Ok(Record { header, payload })
}
