//!
//! Каждая запись самодостаточна и начинается с magic; это — один из трёх
//! инвариантов, без которых невозможен resync (§5.2).
//!
//! Раскладка (little-endian, `RECORD_HEADER_LEN = 32` байта):
//!
//! ```text
//! magic    u32  0x4149_4F53 ("AIOS")
//! len      u32  длина payload, ≤ MAX_RECORD = 1 МиБ, кратно 8
//! crc32c   u32  по payload
//! kind     u8
//! flags    u8   bit0 = payload сжат LZ4, bit1 = есть внешний блоб
//! pad      [2]  нули: выравнивают seq/ts_ns и всю запись на 8 байт
//! seq      u64  монотонный (§5.2)
//! ts_ns    u64
//! payload  [len]
//! ```
//!
//! Поля в документе перечислены в этом же порядке; два байта выравнивания
//! вставлены после `flags`, чтобы `seq` стоял на 8-байтной границе, а вся
//! запись (`32 + len`, `len` кратен 8) была выровнена на 8 байт — как требует
//! §5.2. При чтении байты выравнивания игнорируются (зарезервированы).

use crate::crc32c::crc32c;
use crate::error::Error;

/// Magic записи: `0x41_49_4F_53` («AIOS» в порядке байт big-endian).
///
/// На диск поле пишется little-endian, то есть байтами `53 4F 49 41` — так
/// требует общий little-endian формат §5.2. Для поиска magic в файле есть
/// [`RECORD_MAGIC_BYTES`].
pub const RECORD_MAGIC: u32 = 0x4149_4F53;

/// Байты magic записи в файле (little-endian представление [`RECORD_MAGIC`]).
pub const RECORD_MAGIC_BYTES: [u8; 4] = RECORD_MAGIC.to_le_bytes();

/// Размер заголовка записи вместе с выравниванием, байт.
pub const RECORD_HEADER_LEN: usize = 32;

/// Максимальная длина payload одной записи: 1 МиБ (§5.2).
pub const MAX_RECORD: usize = 1024 * 1024;

/// `flags` bit0: payload сжат LZ4 frame.
pub const FLAG_LZ4: u8 = 0x01;

/// `flags` bit1: payload ссылается на внешний блоб.
pub const FLAG_EXTERNAL_BLOB: u8 = 0x02;

// Смещения полей внутри заголовка записи.
const OFF_MAGIC: usize = 0;
const OFF_LEN: usize = 4;
const OFF_CRC: usize = 8;
const OFF_KIND: usize = 12;
const OFF_FLAGS: usize = 13;
const OFF_PAD: usize = 14;
const OFF_SEQ: usize = 16;
const OFF_TS_NS: usize = 24;

/// Округляет длину вверх до кратного 8 — размер payload записи на диске.
pub const fn align8(len: usize) -> usize {
    (len + 7) & !7
}

/// Вид записи — таблица `kind` из §5.2.
#[repr(u8)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum RecordKind {
    /// Текст пользователя: источник, id клиента, taint=user.
    UserIn = 1,
    /// Текст ответа модели, usage, модель.
    ModelOut = 2,
    /// Шаги плана, уверенность.
    Plan = 3,
    /// Имя возможности, аргументы (redact), хеш результата.
    CapCall = 4,
    /// Вердикт policy engine, правило, причина.
    Policy = 5,
    /// Запись факта в семантическую память: id, скоуп, провенанс.
    MemWrite = 6,
    /// Ссылка на снапшот KV и число токенов префикса.
    KvSnapshot = 7,
    /// Checkpoint: seq, бюджеты, головной хеш цепочки (§5.3).
    Checkpoint = 8,
    /// Код и контекст ошибки.
    Error = 9,
    /// Переход состояния сессии (§5.9).
    SessionState = 10,
    /// Манифест контекста: что попало в контекст модели (§5.6).
    ContextManifest = 11,
    /// Запрос подтверждения у человека: id, действие, TTL.
    Ask = 12,
    /// Головной хеш аудита, вынесенный вовне (§7.4).
    AuditAnchor = 13,
}

impl RecordKind {
    /// Числовое значение поля `kind`.
    pub const fn as_u8(self) -> u8 {
        self as u8
    }

    /// Типизированное представление известного `kind`.
    ///
    /// `None` для неизвестного значения: обрамление записи обязано пережить
    /// запись, вид которой эта версия кода ещё не знает.
    pub const fn from_u8(value: u8) -> Option<Self> {
        match value {
            1 => Some(RecordKind::UserIn),
            2 => Some(RecordKind::ModelOut),
            3 => Some(RecordKind::Plan),
            4 => Some(RecordKind::CapCall),
            5 => Some(RecordKind::Policy),
            6 => Some(RecordKind::MemWrite),
            7 => Some(RecordKind::KvSnapshot),
            8 => Some(RecordKind::Checkpoint),
            9 => Some(RecordKind::Error),
            10 => Some(RecordKind::SessionState),
            11 => Some(RecordKind::ContextManifest),
            12 => Some(RecordKind::Ask),
            13 => Some(RecordKind::AuditAnchor),
            _ => None,
        }
    }
}

/// Заголовок записи (§5.2) без payload.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RecordHeader {
    /// Длина payload, байт. Кратна 8, не больше [`MAX_RECORD`].
    pub len: u32,
    /// `crc32c` payload.
    pub crc32c: u32,
    /// Вид записи, [`RecordKind::as_u8`].
    pub kind: u8,
    /// Флаги, [`FLAG_LZ4`] и [`FLAG_EXTERNAL_BLOB`].
    pub flags: u8,
    /// Монотонный номер записи.
    pub seq: u64,
    /// Время записи, монотонные наносекунды.
    pub ts_ns: u64,
}

impl RecordHeader {
    /// Размер закодированного заголовка записи, байт.
    pub const ENCODED_LEN: usize = RECORD_HEADER_LEN;

    /// Собирает заголовок и считает `crc32c` по payload.
    pub fn new(kind: u8, flags: u8, seq: u64, ts_ns: u64, payload: &[u8]) -> Self {
        RecordHeader {
            len: payload.len() as u32,
            crc32c: crc32c(payload),
            kind,
            flags,
            seq,
            ts_ns,
        }
    }

    /// Кодирует заголовок в 32 байта; байты выравнивания — нули.
    pub fn encode(&self) -> [u8; RECORD_HEADER_LEN] {
        let mut bytes = [0u8; RECORD_HEADER_LEN];
        bytes[OFF_MAGIC..OFF_MAGIC + 4].copy_from_slice(&RECORD_MAGIC_BYTES);
        bytes[OFF_LEN..OFF_LEN + 4].copy_from_slice(&self.len.to_le_bytes());
        bytes[OFF_CRC..OFF_CRC + 4].copy_from_slice(&self.crc32c.to_le_bytes());
        bytes[OFF_KIND] = self.kind;
        bytes[OFF_FLAGS] = self.flags;
        bytes[OFF_PAD] = 0;
        bytes[OFF_PAD + 1] = 0;
        bytes[OFF_SEQ..OFF_SEQ + 8].copy_from_slice(&self.seq.to_le_bytes());
        bytes[OFF_TS_NS..OFF_TS_NS + 8].copy_from_slice(&self.ts_ns.to_le_bytes());
        bytes
    }

    /// Разбирает заголовок записи из 32 байт.
    ///
    /// Проверяет magic и что `len` не больше [`MAX_RECORD`] и кратен 8.
    /// Байты выравнивания игнорируются.
    pub fn decode(bytes: &[u8]) -> Result<Self, Error> {
        if bytes.len() < RECORD_HEADER_LEN {
            return Err(Error::RecordTooShort {
                available: bytes.len(),
            });
        }
        if bytes[OFF_MAGIC..OFF_MAGIC + 4] != RECORD_MAGIC_BYTES {
            return Err(Error::BadRecordMagic { offset: 0 });
        }
        let len = u32::from_le_bytes(
            bytes[OFF_LEN..OFF_LEN + 4]
                .try_into()
                .expect("4 байта"),
        );
        if len as usize > MAX_RECORD {
            return Err(Error::RecordLenTooLarge {
                len,
                max: MAX_RECORD as u32,
            });
        }
        if len % 8 != 0 {
            return Err(Error::RecordLenUnaligned { len });
        }
        Ok(RecordHeader {
            len,
            crc32c: u32::from_le_bytes(
                bytes[OFF_CRC..OFF_CRC + 4]
                    .try_into()
                    .expect("4 байта"),
            ),
            kind: bytes[OFF_KIND],
            flags: bytes[OFF_FLAGS],
            seq: u64::from_le_bytes(
                bytes[OFF_SEQ..OFF_SEQ + 8]
                    .try_into()
                    .expect("8 байт"),
            ),
            ts_ns: u64::from_le_bytes(
                bytes[OFF_TS_NS..OFF_TS_NS + 8]
                    .try_into()
                    .expect("8 байт"),
            ),
        })
    }

    /// Полный размер записи на диске: заголовок + payload (кратен 8).
    pub const fn record_len(&self) -> usize {
        RECORD_HEADER_LEN + self.len as usize
    }

    /// `true`, если payload сжат LZ4 (`flags` bit0).
    pub const fn is_lz4(&self) -> bool {
        self.flags & FLAG_LZ4 != 0
    }

    /// `true`, если payload ссылается на внешний блоб (`flags` bit1).
    pub const fn has_external_blob(&self) -> bool {
        self.flags & FLAG_EXTERNAL_BLOB != 0
    }
}

/// Запись сегмента: заголовок и payload, взятый из буфера сегмента.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Record<'a> {
    /// Заголовок записи.
    pub header: RecordHeader,
    /// Payload ровно `header.len` байт (может включать нулевое выравнивание
    /// до кратного 8 — см. `Writer::append`).
    pub payload: &'a [u8],
}

impl<'a> Record<'a> {
    /// `seq` записи.
    pub const fn seq(&self) -> u64 {
        self.header.seq
    }

    /// `kind` записи.
    pub const fn kind(&self) -> u8 {
        self.header.kind
    }

    /// `flags` записи.
    pub const fn flags(&self) -> u8 {
        self.header.flags
    }

    /// Полный размер записи на диске в байтах.
    pub const fn record_len(&self) -> usize {
        RECORD_HEADER_LEN + self.header.len as usize
    }
}

/// Разбирает запись по смещению `offset` в буфере сегмента.
///
/// Проверяет magic, `len` (предел и кратность 8), границы буфера и `crc32c`
/// payload. `seq` здесь не проверяется — это делает [`crate::SegmentReader`],
/// который знает, какая запись ожидается следующей.
pub fn parse_record_at(bytes: &[u8], offset: usize) -> Result<Record<'_>, Error> {
    let available = bytes.len().saturating_sub(offset);
    if available < RECORD_HEADER_LEN {
        return Err(Error::RecordTooShort { available });
    }
    if bytes[offset..offset + 4] != RECORD_MAGIC_BYTES {
        return Err(Error::BadRecordMagic { offset });
    }
    let header = RecordHeader::decode(&bytes[offset..offset + RECORD_HEADER_LEN])?;
    let len = header.len as usize;
