{"content": "//! Писатель сегментов — ARCHITECTURE §5.1, §5.2.
//!
//! Писатель не знает про файлы: он вызывает [`SegmentStore`], а хранилище
//! (сервис `logd`/`storaged`) решает, куда положить байты. Это позволяет
//! тестировать формат на хосте и использовать тот же код в ядре.
//!
//! Ротация: сегмент не длиннее 16 МиБ (§5.1). Когда следующая запись не
//! помещается, текущий сегмент закрывается, открывается новый с
//! `prev_crc = crc32c предыдущего файла` — цепочка на уровне файлов, чтобы
//! обнаружить удаление сегмента целиком (§5.2).

use crate::crc32c::crc32c_update;
use crate::error::Error;
use crate::record::{RecordHeader, RecordKind, MAX_RECORD, RECORD_HEADER_LEN};
use crate::segment::{SegmentHeader, SegmentKind, SEGMENT_HEADER_LEN};

/// Предельный размер сегмента: 16 МиБ (§5.1 «≤ 16 МиБ на сегмент»).
///
/// Записи не разрезаются: как только следующая запись не помещается в
/// оставшееся место, начинается новый сегмент. Поэтому файл может быть
/// меньше предела на размер хвоста, но никогда не больше него.
pub const SEGMENT_MAX_BYTES: u64 = 16 * 1024 * 1024;

/// Куда писатель складывает байты сегмента.
///
/// Реализации: файл в `storaged`, буфер в памяти (тесты, снапшоты).
pub trait SegmentStore {
    /// Дописывает байты в текущий сегмент.
    fn write(&mut self, bytes: &[u8]) -> Result<(), Error>;

    /// Текущий сегмент закончен: следующие `write` относятся к новому файлу.
    ///
    /// Вызывается только при ротации, до записи заголовка нового сегмента.
    fn rotate(&mut self) -> Result<(), Error>;
}

/// Позиция, на которой закончился лог: ровно то, что кладётся в checkpoint
/// (`segment_id`, `byte_offset`, §5.3), чтобы resume делал seek, а не скан.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SegmentPos {
    /// Номер файла сегмента (`log/000042.seg` → 42).
    pub segment_id: u64,
    /// Смещение конца последней целой записи в этом файле.
    pub byte_offset: u64,
    /// `seq`, который получит следующая запись.
    pub next_seq: u64,
}

/// Что вернул `append`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Appended {
    /// `seq` записанной записи.
    pub seq: u64,
    /// Номер файла сегмента, в который она попала.
    pub segment_id: u64,
    /// Смещение начала записи в файле сегмента.
    pub byte_offset: u64,
    /// Полный размер записи на диске: заголовок + payload (кратен 8).
    pub record_len: usize,
}

/// Append-only писатель сегментов с ротацией.
#[derive(Debug)]
pub struct Writer<S: SegmentStore> {
    store: S,
    kind: SegmentKind,
    segment_id: u64,
    header: SegmentHeader,
    /// `crc32c` всех байт текущего сегмента (заголовок + записи).
    segment_crc: u32,
    /// Сколько байт уже записано в текущий сегмент.
    segment_len: u64,
    next_seq: u64,
}

impl<S: SegmentStore> Writer<S> {
    /// Открывает первый сегмент и пишет его заголовок.
    ///
    /// `segment_id` — номер файла (`log/000042.seg` → 42), `seq_first` —
    /// `seq` первой записи, `prev_crc` — `crc32c` предыдущего файла (0, если
    /// это первый сегмент сессии/аудита).
    pub fn create(
        store: S,
        kind: SegmentKind,
        segment_id: u64,
        seq_first: u64,
        created_ns: u64,
        prev_crc: u32,
    ) -> Result<Self, Error> {
        let header = SegmentHeader::new(kind, seq_first, created_ns, prev_crc);
        let mut writer = Writer {
            store,
            kind,
            segment_id,
            header,
            segment_crc: 0,
            segment_len: 0,
            next_seq: seq_first,
        };
        writer.write_header()?;
        Ok(writer)
    }

    fn write_header(&mut self) -> Result<(), Error> {
        let bytes = self.header.encode();
        self.store.write(&bytes)?;
        self.segment_crc = crc32c_update(self.segment_crc, &bytes);
        self.segment_len += SEGMENT_HEADER_LEN as u64;
        Ok(())
    }

    fn rotate(&mut self, created_ns: u64) -> Result<(), Error> {
        self.store.rotate()?;
        self.segment_id += 1;
        // Цепочка файлов: следующий сегмент помнит crc предыдущего.
        self.header = SegmentHeader::new(self.kind, self.next_seq, created_ns, self.segment_crc);
        self.segment_crc = 0;
        self.segment_len = 0;
        self.write_header()
    }

    /// Дописывает запись и возвращает её `seq`.
    ///
    /// `payload` — уже сериализованные данные (для записей сессии — CBOR,
    /// §5.12); его длина обязана быть кратна 8 (§5.2: инвариант resync).
    ///
    /// `ts_ns` — монотонное время записи; оно же становится `created_ns`
    /// нового сегмента, если этот вызов вызвал ротацию.
    pub fn append(
        &mut self,
        kind: RecordKind,
        flags: u8,
        ts_ns: u64,
        payload: &[u8],
    ) -> Result<Appended, Error> {
        if payload.len() > MAX_RECORD {
            return Err(Error::PayloadTooLarge {
                len: payload.len(),
                max: MAX_RECORD,
            });
        }
        if payload.len() % 8 != 0 {
            return Err(Error::PayloadUnaligned { len: payload.len() });
        }

        let record_len = RECORD_HEADER_LEN + payload.len();
        if self.segment_len + record_len as u64 > SEGMENT_MAX_BYTES {
            self.rotate(ts_ns)?;
        }

        let header = RecordHeader::new(kind.as_u8(), flags, self.next_seq, ts_ns, payload);
        let start = self.segment_len;
        let encoded = header.encode();
        self.store.write(&encoded)?;
        self.store.write(payload)?;
        self.segment_crc = crc32c_update(self.segment_crc, &encoded);
        self.segment_crc = crc32c_update(self.segment_crc, payload);
        self.segment_len += record_len as u64;
        self.next_seq += 1;

        Ok(Appended {
            seq: header.seq,
            segment_id: self.segment_id,
            byte_offset: start,
            record_len,
        })
    }

    /// Где сейчас кончается лог — для checkpoint (§5.3).
    pub fn position(&self) -> SegmentPos {
        SegmentPos {
            segment_id: self.segment_id,
            byte_offset: self.segment_len,
            next_seq: self.next_seq,
        }
    }

    /// Заголовок текущего сегмента.
    pub fn header(&self) -> SegmentHeader {
        self.header
    }

    /// `crc32c` текущего сегмента на текущий момент (если сегмент закрыть
    /// сейчас — это его `prev_crc` для следующего).
    pub fn segment_crc(&self) -> u32 {
        self.segment_crc
    }

    /// Номер текущего файла сегмента.
    pub fn segment_id(&self) -> u64 {
        self.segment_id
    }

    /// Забирает хранилище обратно (например, чтобы закрыть файл).
    pub fn into_inner(self) -> S {
        self.store
    }
}
