{"content": "//! Читатель сегментов с resync — ARCHITECTURE §5.2.
//!
//! Сканируем от последнего валидного смещения: ищем magic (4 байта, шанс
//! ложного срабатывания 2⁻³² на позицию), проверяем `len ≤ MAX_RECORD` и
//! границы, считаем `crc32c`, ждём ожидаемый `seq`. Не сходится — сдвиг на
//! 1 байт и повтор.
//!
//! Обрыв (torn write) отличается от повреждения середины:
//! * magic на ожидаемом месте есть, запись не валидна, и дальше в файле нет
//!   ни одной валидной записи → [`ReaderStatus::Torn`]: хвост отбрасывается;
//! * после сбоя нашлась следующая валидная запись (значит, часть записей
//!   потеряна, но файл продолжается) → [`ReaderStatus::Damaged`], чтение
//!   продолжается с найденного места;
//! * magic нет вовсе (мусор вместо начала записи) и валидной записи дальше
//!   нет → [`ReaderStatus::Damaged`]: сегмент дальше только читается.
//!
//! Уточнение к §5.2, зафиксированное в отчёте T5: документ называет
//! «повреждением середины» только случай «magic не найден на всей длине».
//! Порча байта в payload середины файла выглядит как «magic есть, crc не
//! сходится», но хвост после неё читается — это тоже повреждение, а не
//! обрыв: иначе тест «порча в середине → damaged» невыполним.

use crate::error::Error;
use crate::record::{
    parse_record_at, Record, RECORD_HEADER_LEN, RECORD_MAGIC_BYTES,
};
use crate::segment::{SegmentHeader, SEGMENT_HEADER_LEN};

/// Чем кончилось чтение сегмента.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReaderStatus {
    /// Все записи прочитаны, файл закончился ровно на границе записи.
    Clean,
    /// Хвост оборван (файл обрезан при записи); прочитанный префикс цел.
    Torn {
        /// Смещение, с которого начинается неполная запись.
        at: usize,
    },
    /// В середине файла повреждение: часть записей потеряна, чтение
    /// продолжилось после ресинка.
    Damaged {
        /// Смещение, на котором обнаружено повреждение.
        at: usize,
    },
}

impl ReaderStatus {
    /// `true`, если файл прочитан целиком без потерь.
    pub const fn is_clean(self) -> bool {
        matches!(self, ReaderStatus::Clean)
    }

    /// `true`, если хвост оборван.
    pub const fn is_torn(self) -> bool {
        matches!(self, ReaderStatus::Torn { .. })
    }

    /// `true`, если в середине файла повреждение.
    pub const fn is_damaged(self) -> bool {
        matches!(self, ReaderStatus::Damaged { .. })
    }
}

/// Итератор по записям одного сегмента.
///
/// Заголовок сегмента разбирается лениво — при первом обращении к записи или
/// к [`SegmentReader::header`]. Ошибки не прерывают итерацию исключением:
/// они видны в [`SegmentReader::status`], а итератор просто заканчивается.
#[derive(Debug)]
pub struct SegmentReader<'a> {
    buf: &'a [u8],
    pos: usize,
    last_seq: Option<u64>,
    status: ReaderStatus,
    header: Option<SegmentHeader>,
    stopped: bool,
    records: u64,
    last_valid_offset: usize,
}

impl<'a> SegmentReader<'a> {
    /// Создаёт читатель поверх байт файла сегмента.
    pub fn new(buf: &'a [u8]) -> Self {
        SegmentReader {
            buf,
            pos: 0,
            last_seq: None,
            status: ReaderStatus::Clean,
            header: None,
            stopped: false,
            records: 0,
            last_valid_offset: 0,
        }
    }

    /// Разбирает и проверяет заголовок сегмента (64 байта).
    ///
    /// При обрыве на заголовке статус становится
    /// [`ReaderStatus::Torn`], при неверном заголовке —
    /// [`ReaderStatus::Damaged`] со смещением 0.
    pub fn header(&mut self) -> Result<SegmentHeader, Error> {
        if let Some(header) = self.header {
            return Ok(header);
        }
        if self.buf.len() < SEGMENT_HEADER_LEN {
            self.status = ReaderStatus::Torn {
                at: self.buf.len(),
            };
            self.stopped = true;
            return Err(Error::IncompleteSegmentHeader {
                available: self.buf.len(),
            });
        }
        match SegmentHeader::decode(&self.buf[..SEGMENT_HEADER_LEN]) {
            Ok(header) => {
                self.header = Some(header);
                self.pos = SEGMENT_HEADER_LEN;
                Ok(header)
            }
            Err(error) => {
                self.status = ReaderStatus::Damaged { at: 0 };
                self.stopped = true;
                Err(error)
            }
        }
    }

    /// Следующая валидная запись или `None`, если файл кончился (целиком,
    /// обрывом или повреждением — см. [`SegmentReader::status`]).
    pub fn next_record(&mut self) -> Option<Record<'a>> {
        if self.stopped {
            return None;
        }
        loop {
            let header = match self.header() {
                Ok(header) => header,
                Err(_) => return None,
            };
            let remaining = self.buf.len() - self.pos;
            if remaining == 0 {
                self.stopped = true;
                return None;
            }
            if remaining < RECORD_HEADER_LEN {
                // Меньше заголовка записи — валидной записи тут быть не может:
                // это только обрыв.
                self.status = ReaderStatus::Torn { at: self.pos };
                self.stopped = true;
                return None;
            }

            let expected = Some(match self.last_seq {
                Some(seq) => seq + 1,
                None => header.seq_first,
            });
            match self.parse_at(self.pos, expected) {
                Ok(record) => {
                    self.accept(record);
                    return Some(record);
                }
                Err(_) => match self.resync() {
                    Some(record) => {
                        self.accept(record);
                        return Some(record);
                    }
                    None => {
                        self.stopped = true;
                        return None;
                    }
                },
            }
        }
    }

    fn parse_at(&self, offset: usize, expected: Option<u64>) -> Result<Record<'a>, Error> {
        let record = parse_record_at(self.buf, offset)?;
        if let Some(expected) = expected {
            if record.header.seq != expected {
                return Err(Error::UnexpectedSeq {
                    expected,
                    actual: record.header.seq,
                });
            }
        }
        Ok(record)
    }

    fn accept(&mut self, record: Record<'a>) {
        self.last_seq = Some(record.header.seq);
        self.pos += record.record_len();
        self.last_valid_offset = self.pos;
        self.records += 1;
    }

    /// Сканирует байт за байтом от текущей позиции в поисках следующей
    /// валидной записи. Возвращает её и фиксирует повреждение в статусе.
    fn resync(&mut self) -> Option<Record<'a>> {
        let start = self.pos;
        let min_seq = match self.last_seq {
            Some(seq) => seq + 1,
            None => self.header.map_or(0, |header| header.seq_first),
        };
        let mut candidate = start + 1;
        while candidate + RECORD_HEADER_LEN <= self.buf.len() {
            if self.buf[candidate..candidate + 4] == RECORD_MAGIC_BYTES {
                if let Ok(record) = parse_record_at(self.buf, candidate) {
                    // После потери записей seq прыгает вперёд; назад — нельзя.
                    if record.header.seq >= min_seq {
                        if self.status.is_clean() {
                            self.status = ReaderStatus::Damaged { at: start };
                        }
                        self.pos = candidate;
                        return Some(record);
                    }
                }
            }
            candidate += 1;
        }

        let magic_present =
            start + 4 <= self.buf.len() && self.buf[start..start + 4] == RECORD_MAGIC_BYTES;
        self.status = if magic_present {
            ReaderStatus::Torn { at: start }
        } else {
            ReaderStatus::Damaged { at: start }
        };
        None
    }

    /// Чем кончилось (или пока кончается) чтение.
    pub fn status(&self) -> ReaderStatus {
        self.status
    }

    /// Сколько записей уже прочитано.
    pub fn records_read(&self) -> u64 {
        self.records
    }

    /// Смещение сразу за последней прочитанной целой записью.
    ///
    /// Это якорь для checkpoint'а: `seek(byte_offset)` вместо скана.
    pub fn last_valid_offset(&self) -> usize {
        self.last_valid_offset
    }

    /// `seq` последней прочитанной записи.
    pub fn last_seq(&self) -> Option<u64> {
        self.last_seq
    }

    /// `true`, если читатель больше не выдаст записей.
    pub fn is_stopped(&self) -> bool {
        self.stopped
    }
}

impl<'a> Iterator for SegmentReader<'a> {
    type Item = Record<'a>;

    fn next(&mut self) -> Option<Self::Item> {
        self.next_record()
    }
}
