///
/// Несовпадение версии — отказ разбора, а не «как-нибудь».
pub const CHECKPOINT_SCHEMA_VERSION: u8 = 1;

/// Бюджеты сессии на момент checkpoint'а (§5.3).
///
/// Поля объявлены в каноническом порядке ключей (§5.12):
/// `cost_us` (7), `wall_ms` (7), `tokens_in` (9), `tokens_out` (10).
#[cfg(feature = "cbor")]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Budgets {
    /// Потраченные микросекунды CPU/инференса.
    pub cost_us: u64,
    /// Потраченное wall-clock время, мс.
    pub wall_ms: u64,
    /// Токенов на входе.
    pub tokens_in: u64,
    /// Токенов на выходе.
    pub tokens_out: u64,
}

/// Ссылка на снапшот KV-cache (§5.3, ключ — §5.4).
///
/// Поля объявлены в каноническом порядке ключей (§5.12):
/// `crc` (3), `bytes` (5), `tokens` (6), `key_hash` (8).
#[cfg(feature = "cbor")]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct KvSnapshotRef {
    /// `crc32c` файла снапшота.
    pub crc: u32,
    /// Размер снапшота, байт.
    pub bytes: u64,
    /// Число токенов префикса, покрытых снапшотом.
    pub tokens: u64,
    /// Хеш `SnapshotKey` (§5.4) — 32 байта.
    #[serde(with = "serde_hash32")]
    pub key_hash: [u8; 32],
}

/// Checkpoint сессии (§5.3).
///
/// Поля объявлены в каноническом порядке ключей (§5.12):
/// `kv` (2), `seq` (3), `facts` (5), `budgets` (7), `model_fp` (8),
/// `segment_id` (10), `byte_offset` (11), `transcript_head_hash` (20).
