            return Err(Error::UnexpectedRecordKind {
                expected: RecordKind::Checkpoint.as_u8(),
                actual: record.header.kind,
            });
        }
        Self::decode_payload(record.payload)
    }

    /// Пишет checkpoint в лог записью `kind = 8` и возвращает её позицию.
    pub fn append<S: SegmentStore>(
        &self,
        writer: &mut Writer<S>,
        ts_ns: u64,
    ) -> Result<Appended, Error> {
        let payload = self.encode_payload()?;
        writer.append(RecordKind::Checkpoint, 0, ts_ns, &payload)
    }
}

/// Канонический CBOR (§5.12): контроль формы, а не схемы.
///
/// Валидатор не знает про поля checkpoint'а — он проверяет ровно то, что
/// делает канонизацию детерминированной: definite-length, минимальные числа,
/// сортировку ключей map, отсутствие float, UTF-8 в текстовых строках.
#[cfg(feature = "cbor")]
pub mod canonical {
    /// Максимальная глубина вложенности, которую принимает валидатор.
    pub const MAX_DEPTH: u8 = 16;

    /// Проверяет, что `bytes` — одно CBOR-значение в канонической форме.
    ///
    /// Возвращает длину значения в байтах: дальше в payload может быть только
    /// нулевое выравнивание. Причина отказа — короткая строка для отчёта.
    pub fn check(bytes: &[u8]) -> Result<usize, &'static str> {
        item(bytes, 0, 0)
    }

    /// Читает аргумент CBOR (длину/значение) и проверяет минимальность.
    fn read_argument(bytes: &[u8], pos: usize, info: u8) -> Result<(u64, usize), &'static str> {
        match info {
            0..=23 => Ok((u64::from(info), pos)),
            24 => {
                let byte = *bytes.get(pos).ok_or("CBOR обрезан")?;
                if byte < 24 {
                    return Err("число закодировано не минимальной длиной");
                }
                Ok((u64::from(byte), pos + 1))
            }
            25 => {
                let raw = bytes.get(pos..pos + 2).ok_or("CBOR обрезан")?;
                let value = u64::from(u16::from_be_bytes([raw[0], raw[1]]));
                if value <= 0xFF {
                    return Err("число закодировано не минимальной длиной");
                }
                Ok((value, pos + 2))
            }
            26 => {
                let raw = bytes.get(pos..pos + 4).ok_or("CBOR обрезан")?;
                let value = u64::from(u32::from_be_bytes([raw[0], raw[1], raw[2], raw[3]]));
                if value <= 0xFFFF {
                    return Err("число закодировано не минимальной длиной");
                }
                Ok((value, pos + 4))
            }
            27 => {
                let raw = bytes.get(pos..pos + 8).ok_or("CBOR обрезан")?;
                let value = u64::from_be_bytes([
                    raw[0], raw[1], raw[2], raw[3], raw[4], raw[5], raw[6], raw[7],
                ]);
                if value <= 0xFFFF_FFFF {
                    return Err("число закодировано не минимальной длиной");
                }
                Ok((value, pos + 8))
            }
            28..=30 => Err("зарезервированное additional info"),
            31 => Err("indefinite-length запрещён канонической формой"),
            _ => Err("недопустимое additional info"),
        }
    }

    fn bounds(bytes: &[u8], start: usize, len: u64) -> Result<usize, &'static str> {
        let len = usize::try_from(len).map_err(|_| "длина не влезает в usize")?;
        let end = start.checked_add(len).ok_or("переполнение длины CBOR")?;
        if end > bytes.len() {
            return Err("CBOR обрезан");
        }
        Ok(end)
    }

    fn item(bytes: &[u8], pos: usize, depth: u8) -> Result<usize, &'static str> {
        if depth > MAX_DEPTH {
            return Err("слишком глубокая вложенность CBOR");
        }
        let initial = *bytes.get(pos).ok_or("CBOR обрезан")?;
        let major = initial >> 5;
        let info = initial & 0x1F;
        if info == 31 {
            return Err("indefinite-length запрещён канонической формой");
        }
        match major {
            // Беззнаковые/отрицательные целые.
            0 | 1 => {
                let (_value, next) = read_argument(bytes, pos + 1, info)?;
                Ok(next)
            }
            // Байтовые строки.
            2 => {
                let (len, next) = read_argument(bytes, pos + 1, info)?;
                bounds(bytes, next, len)
            }
            // Текстовые строки: UTF-8, NFC — забота сериализатора; здесь UTF-8.
            3 => {
                let (len, next) = read_argument(bytes, pos + 1, info)?;
                let end = bounds(bytes, next, len)?;
                core::str::from_utf8(&bytes[next..end]).map_err(|_| "текстовая строка не UTF-8")?;
                Ok(end)
            }
            // Массивы.
            4 => {
                let (len, mut next) = read_argument(bytes, pos + 1, info)?;
                if len > bytes.len() as u64 {
                    return Err("длина массива больше самих данных");
                }
                for _ in 0..len {
                    next = item(bytes, next, depth + 1)?;
                }
                Ok(next)
            }
            // Map: ключи обязаны быть текстовыми, порядок — (длина, байты).
            5 => {
                let (len, mut next) = read_argument(bytes, pos + 1, info)?;
                if len > bytes.len() as u64 {
                    return Err("длина map больше самих данных");
                }
                let mut previous: Option<&[u8]> = None;
                for _ in 0..len {
                    let key_initial = *bytes.get(next).ok_or("CBOR обрезан")?;
                    if key_initial >> 5 != 3 {
                        return Err("ключ map обязан быть текстовой строкой");
                    }
                    let (key_len, key_start) = read_argument(bytes, next + 1, key_initial & 0x1F)?;
                    let key_end = bounds(bytes, key_start, key_len)?;
                    let key = &bytes[key_start..key_end];
                    core::str::from_utf8(key).map_err(|_| "ключ map не UTF-8")?;
                    if let Some(previous) = previous {
                        if key.len() < previous.len()
                            || (key.len() == previous.len() && key <= previous)
                        {
                            return Err(
                                "ключи map не в каноническом порядке (длина, затем байты)",
                            );
                        }
                    }
                    previous = Some(key);
                    next = item(bytes, key_end, depth + 1)?;
                }
                Ok(next)
            }
            // Теги: разрешены, содержимое проверяется как обычное значение.
            6 => {
                let (_tag, next) = read_argument(bytes, pos + 1, info)?;
                item(bytes, next, depth + 1)
            }
            // Простые значения и float.
            7 => match info {
                0..=23 => Ok(pos + 1),
                24 => {
                    *bytes.get(pos + 1).ok_or("CBOR обрезан")?;
                    Ok(pos + 2)
                }
                25..=27 => Err("float запрещён в канонических структурах (§5.12)"),
                _ => Err("недопустимое additional info"),
            },
            _ => Err("недопустимый major type"),
        }
    }
}

#[cfg(feature = "cbor")]
mod serde_hash32 {
    use alloc::vec::Vec;
    use serde::{Deserialize, Deserializer, Serializer};

    pub fn serialize<S: Serializer>(value: &[u8; 32], serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_bytes(value)
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(deserializer: D) -> Result<[u8; 32], D::Error> {
        let bytes = Vec::<u8>::deserialize(deserializer)?;
        <[u8; 32]>::try_from(bytes.as_slice())
            .map_err(|_| serde::de::Error::custom("ожидается 32 байта"))
    }
}

#[cfg(feature = "cbor")]
mod serde_facts {
    use alloc::vec::Vec;
    use serde::{Deserialize, Deserializer, Serialize, Serializer};

    /// Байтовая строка CBOR без промежуточной аллокации.
    struct Bytes<'a>(&'a [u8]);

    impl Serialize for Bytes<'_> {
        fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
            serializer.serialize_bytes(self.0)
        }
    }

    pub fn serialize<S: Serializer>(
        facts: &[[u8; 16]],
        serializer: S,
    ) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeSeq;
        let mut seq = serializer.serialize_seq(Some(facts.len()))?;
        for fact in facts {
            seq.serialize_element(&Bytes(fact))?;
        }
        seq.end()
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(
        deserializer: D,
    ) -> Result<Vec<[u8; 16]>, D::Error> {
        let items = Vec::<Vec<u8>>::deserialize(deserializer)?;
        items
            .into_iter()
            .map(|item| {
                <[u8; 16]>::try_from(item.as_slice())
                    .map_err(|_| serde::de::Error::custom("ожидается 16 байт fact_id"))
            })
            .collect()
    }
}
