#[cfg(feature = "cbor")]
mod serde_facts {
    use alloc::vec::Vec;
    use serde::{Deserialize, Deserializer, Serialize, Serializer};

    /// Байтовая строка CBOR без промежуточной аллокации.
    struct Bytes<'a>(&'a [u8]);

    impl Serialize for Bytes<'_> {
        fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
            serializer.serialize_bytes(self.0)
        }
    }

    pub fn serialize<S: Serializer>(
        facts: &[[u8; 16]],
        serializer: S,
    ) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeSeq;
        let mut seq = serializer.serialize_seq(Some(facts.len()))?;
        for fact in facts {
            seq.serialize_element(&Bytes(fact))?;
        }
        seq.end()
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(
        deserializer: D,
    ) -> Result<Vec<[u8; 16]>, D::Error> {
        let items = Vec::<Vec<u8>>::deserialize(deserializer)?;
        items
            .into_iter()
            .map(|item| {
                <[u8; 16]>::try_from(item.as_slice())
                    .map_err(|_| serde::de::Error::custom("ожидается 16 байт fact_id"))
            })
            .collect()
    }
