#[test]
fn truncation_at_every_byte_is_torn_or_clean_never_damaged() {
    let payloads = payloads(); // 8,16,24,40
    let full = build_segment_with(&payloads);
    // границы записей
    let mut boundaries = vec![SEGMENT_HEADER_LEN];
    let mut offset = SEGMENT_HEADER_LEN;
    for payload in &payloads { offset += RECORD_HEADER_LEN + payload.len(); boundaries.push(offset); }
    assert_eq!(offset, full.len());

    // сколько записей целиком помещается в префикс длиной len
    let complete = |len: usize| boundaries.iter().filter(|&&b| b <= len).count() - 1;

    for len in 0..=full.len() {
        let prefix = &full[..len];
        let mut reader = SegmentReader::new(prefix);
        let records: Vec<Record<'_>> = reader.by_ref().collect();
        let expected = complete(len);
        assert_eq!(records.len(), expected, "len={len}: прочитано {} записей, ожидалось {expected}", records.len());
        // префикс цел: записи совпадают с исходными по seq и payload
        for (index, record) in records.iter().enumerate() {
            assert_eq!(record.header.seq, 1 + index as u64);
            assert_eq!(record.payload, &payloads[index][..]);
        }
        // хвост помечен torn, но никогда — damaged
        assert!(!reader.status().is_damaged(), "len={len}: неожиданный damaged {:?}", reader.status());
        let at_boundary = boundaries.contains(&len);
        if len == full.len() || at_boundary {
            assert_eq!(reader.status(), ReaderStatus::Clean, "len={len}");
        } else {
            assert_eq!(reader.status(), ReaderStatus::Torn { at: if len < SEGMENT_HEADER_LEN { len } else { boundaries[complete(len)] } }, "len={len}");
        }
    }
